import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"下载安装","description":"","frontmatter":{},"headers":[],"relativePath":"document/install.md","filePath":"document/install.md","lastUpdated":1783774350000}`),a={name:`document/install.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /document/install.md for this page in Markdown format</div><h1 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to “下载安装”">​</a></h1><h2 id="平台支持" tabindex="-1">平台支持 <a class="header-anchor" href="#平台支持" aria-label="Permalink to “平台支持”">​</a></h2><p>官方 Release 支持以下平台</p><table tabindex="0"><thead><tr><th style="text-align:left;">平台</th><th style="text-align:left;">架构</th></tr></thead><tbody><tr><td style="text-align:left;">Windows <sup><a href="#platform-note-1">[1]</a></sup></td><td style="text-align:left;">x86 / amd64 / arm32 / arm64</td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;">amd64 / arm64</td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;">x86 / amd64 / arm / arm64 / mips64 / mips / ppc64 / s390x / riscv64</td></tr><tr><td style="text-align:left;">FreeBSD</td><td style="text-align:left;">x86 / amd64</td></tr><tr><td style="text-align:left;">OpenBSD</td><td style="text-align:left;">x86 / amd64</td></tr></tbody></table><p><small id="platform-note-1">[1] Windows 7 已被 golang 官方停止支持，Xray 使用 patched go 独立发布构建提供支持，win7 用户请使用 -win7 后缀的发布。</small></p><p>Xray 积极跟进 golang 版本，除 win7 外最低操作系统版本支持请参考发布时对应的最新的 go release note。</p><p>未像部分类似项目一样提供 amd64 v2 v3 等构建，因为经过测试性能并没有明显提升，关键函数中很多使用了运行时检测来自动使用扩展指令集。</p><h2 id="下载-xray" tabindex="-1">下载 Xray <a class="header-anchor" href="#下载-xray" aria-label="Permalink to “下载 Xray”">​</a></h2><p>预编译的二进制 ZIP 格式压缩包可在 <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a> 中找到。</p><p>下载对应平台的压缩包，解压后即可使用。</p><h2 id="验证安装包" tabindex="-1">验证安装包 <a class="header-anchor" href="#验证安装包" aria-label="Permalink to “验证安装包”">​</a></h2><p>Xray 提供两种验证方式：</p><ul><li>ZIP 压缩包的 SHA1 / SHA256 摘要</li><li>可复现构建：请参照 <a href="./../development/intro/compile.html">编译 Xray</a></li></ul><h2 id="windows-安装方式" tabindex="-1">Windows 安装方式 <a class="header-anchor" href="#windows-安装方式" aria-label="Permalink to “Windows 安装方式”">​</a></h2><ul><li>在 <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a> 下载适用于 Windows 平台的 ZIP 压缩包，解压后可得到可执行文件 <code>xray.exe</code>，然后<a href="./command.html">通过命令行带参数运行</a> 即可</li></ul><h2 id="macos-安装方式" tabindex="-1">macOS 安装方式 <a class="header-anchor" href="#macos-安装方式" aria-label="Permalink to “macOS 安装方式”">​</a></h2><ul><li>在 <a href="https://github.com/xtls/Xray-core/releases" target="_blank" rel="noreferrer">Github Releases</a> 下载适用于 macOS 平台的 ZIP 压缩包，解压后可得到可执行文件 <code>xray</code> ，然后<a href="./command.html">通过命令行带参数运行</a> 即可</li><li>通过 <a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a> 包管理器安装：<code>brew install xray</code></li><li><a href="https://github.com/N4FA/homebrew-xray" target="_blank" rel="noreferrer">homebrew-xray</a> 感谢<a href="https://github.com/N4FA" target="_blank" rel="noreferrer">@N4FA</a></li></ul><h2 id="linux-安装方式" tabindex="-1">Linux 安装方式 <a class="header-anchor" href="#linux-安装方式" aria-label="Permalink to “Linux 安装方式”">​</a></h2><h3 id="安装脚本与项目" tabindex="-1">安装脚本与项目 <a class="header-anchor" href="#安装脚本与项目" aria-label="Permalink to “安装脚本与项目”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">项目</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/XTLS/Xray-install" target="_blank" rel="noreferrer">XTLS/Xray-install</a>（<strong>官方</strong>）</td><td style="text-align:left;">官方维护的 Linux 安装脚本</td></tr><tr><td style="text-align:left;">Linux Script</td><td style="text-align:left;"><a href="https://github.com/team-cloudchaser/tempest" target="_blank" rel="noreferrer">tempest</a></td><td style="text-align:left;">支持 <a href="https://systemd.io" target="_blank" rel="noreferrer"><code>Systemd</code></a> 与 <a href="https://github.com/OpenRC/openrc" target="_blank" rel="noreferrer"><code>OpenRC</code></a></td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/zxcvos/Xray-script" target="_blank" rel="noreferrer">Xray-REALITY</a></td><td style="text-align:left;">一键安装方案</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/aleskxyz/reality-ezpz" target="_blank" rel="noreferrer">reality-ezpz</a></td><td style="text-align:left;">一键安装方案</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/hello-yunshu/Xray_bash_onekey" target="_blank" rel="noreferrer">Xray_bash_onekey</a></td><td style="text-align:left;">一键安装方案</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/mack-a/v2ray-agent" target="_blank" rel="noreferrer">v2ray-agent</a></td><td style="text-align:left;">一键安装方案</td></tr><tr><td style="text-align:left;">One Click</td><td style="text-align:left;"><a href="https://github.com/proxysu/ProxySU" target="_blank" rel="noreferrer">ProxySU</a></td><td style="text-align:left;">一键安装方案</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/Asterisk4Magisk/Xray4Magisk" target="_blank" rel="noreferrer">Xray4Magisk</a></td><td style="text-align:left;">适用于 Magisk 环境</td></tr><tr><td style="text-align:left;">Magisk</td><td style="text-align:left;"><a href="https://github.com/E7KMbb/Xray_For_Magisk" target="_blank" rel="noreferrer">Xray_For_Magisk</a></td><td style="text-align:left;">适用于 Magisk 环境</td></tr></tbody></table><h3 id="包管理器与发行版仓库" tabindex="-1">包管理器与发行版仓库 <a class="header-anchor" href="#包管理器与发行版仓库" aria-label="Permalink to “包管理器与发行版仓库”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">项目</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Arch User Repository</td><td style="text-align:left;"><a href="https://wiki.archlinux.org/index.php/AUR_helpers" target="_blank" rel="noreferrer">AUR helpers</a></td><td style="text-align:left;">以 <a href="https://github.com/Jguer/yay" target="_blank" rel="noreferrer">yay</a> 为例，可通过 <code>yay -S xray</code> 安装</td></tr><tr><td style="text-align:left;">Arch Linux CN</td><td style="text-align:left;"><a href="https://www.archlinuxcn.org/archlinux-cn-repo-and-mirror/" target="_blank" rel="noreferrer">Arch Linux CN 仓库</a></td><td style="text-align:left;">添加仓库后，在 root 用户下使用 <code>pacman -S xray</code> 安装</td></tr><tr><td style="text-align:left;">Linuxbrew</td><td style="text-align:left;"><a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a></td><td style="text-align:left;">用法与 Homebrew 一致：<code>brew install xray</code></td></tr><tr><td style="text-align:left;">Gentoo Portage</td><td style="text-align:left;"><a href="https://github.com/microcai/gentoo-zh" target="_blank" rel="noreferrer">Gentoo-zh</a></td><td style="text-align:left;">适用于 Systemd 系统；使用 layman 或 eselect-repository 添加 Overlay 后安装</td></tr></tbody></table><h2 id="docker-安装方式" tabindex="-1">Docker 安装方式 <a class="header-anchor" href="#docker-安装方式" aria-label="Permalink to “Docker 安装方式”">​</a></h2><p>目前提供两种不同风格的 Docker 映像：</p><ul><li><p><a href="https://ghcr.io/xtls/xray-core" target="_blank" rel="noreferrer">ghcr.io/xtls/xray-core</a>（<strong>官方</strong>）<br> 无 root 权限、无 shell 环境、支持更多的架构。由官方库编译并构建支持追溯。牺牲了便利性来追求更极端的安全性</p><details class="details custom-block"><summary>文件结构</summary><ul><li><code>/usr/local/bin/xray</code>：Xray 主程序（拥有者是 <code>root:root</code>、文件权限 <code>755</code>）</li><li><code>/usr/local/etc/xray/</code>：配置文件目录（挂载点）（拥有者是 <code>root:root</code>、目录权限 <code>755</code>、文件权限 <code>644</code>） <ul><li>00_log.json</li><li>01_api.json</li><li>02_dns.json</li><li>03_routing.json</li><li>04_policy.json</li><li>05_inbounds.json</li><li>06_outbounds.json</li><li>07_stats.json</li><li>08_fakedns.json</li><li>09_metrics.json</li><li>10_observatory.json</li><li>11_geodata.json</li><li>12_env.json</li><li>99_version.json</li></ul></li><li><code>/usr/local/share/xray/</code>：资源文件目录，存放了 Loyalsoldier 版本地理位置数据文件（拥有者是 <code>65532:65532</code>、目录权限 <code>755</code>、文件权限 <code>644</code>） <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li><li><code>/var/log/xray/</code>：日志文件目录（挂载点）（目录拥有者是 <code>root:root</code>、权限 <code>755</code>；文件拥有者是 <code>65532:65532</code>、权限 <code>600</code>） <ul><li>access.log</li><li>error.log</li></ul></li></ul></details></li><li><p><a href="https://hub.docker.com/r/teddysun/xray" target="_blank" rel="noreferrer">teddysun/xray</a><br> 有 root 权限、有 shell 环境、兼容所有 Alpine 支持的架构。由私人服务器 dl.lamp.sh 编译并构建。使用起来更便捷</p><details class="details custom-block"><summary>文件结构</summary><ul><li><code>/usr/bin/xray</code>：Xray 主程序</li><li><code>/etc/xray/config.json</code>：单一配置文件（其所在目录为挂载点）</li><li><code>/usr/share/xray/</code>：资源文件目录，存放了 v2fly 版本地理位置数据文件 <ul><li>geoip.dat</li><li>geosite.dat</li></ul></li></ul></details></li></ul><h2 id="第三方图形化客户端" tabindex="-1">第三方图形化客户端 <a class="header-anchor" href="#第三方图形化客户端" aria-label="Permalink to “第三方图形化客户端”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">平台</th><th style="text-align:left;">项目</th></tr></thead><tbody><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall" target="_blank" rel="noreferrer">PassWall</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/Openwrt-Passwall/openwrt-passwall2" target="_blank" rel="noreferrer">PassWall 2</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/fw876/helloworld" target="_blank" rel="noreferrer">ShadowSocksR Plus+</a></td></tr><tr><td style="text-align:left;">OpenWrt</td><td style="text-align:left;"><a href="https://github.com/yichya/luci-app-xray" target="_blank" rel="noreferrer">luci-app-xray</a> (<a href="https://github.com/yichya/openwrt-xray" target="_blank" rel="noreferrer">openwrt-xray</a>)</td></tr><tr><td style="text-align:left;">Asuswrt-Merlin</td><td style="text-align:left;"><a href="https://github.com/DanielLavrushin/asuswrt-merlin-xrayui" target="_blank" rel="noreferrer">XRAYUI</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/InvisibleManVPN/InvisibleMan-XRayClient" target="_blank" rel="noreferrer">Invisible Man - Xray</a></td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayNG" target="_blank" rel="noreferrer">v2rayNG</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/XTLS/X-flutter" target="_blank" rel="noreferrer">X-flutter</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/SaeedDev94/Xray" target="_blank" rel="noreferrer">SaeedDev94/Xray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/lhear/SimpleXray" target="_blank" rel="noreferrer">SimpleXray</a></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a> (<a href="https://apps.apple.com/us/app/happ-proxy-utility-for-tv/id6748297274" target="_blank" rel="noreferrer">tvOS</a>)</td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/foxray/id6448898396" target="_blank" rel="noreferrer">FoXray</a></td></tr><tr><td style="text-align:left;">iOS / macOS arm64 / tvOS</td><td style="text-align:left;"><a href="https://apps.apple.com/app/streisand/id6450534064" target="_blank" rel="noreferrer">Streisand</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://apps.apple.com/app/happ-proxy-utility/id6504287215" target="_blank" rel="noreferrer">Happ</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/yanue/V2rayU" target="_blank" rel="noreferrer">V2rayU</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/tzmax/V2RayXS" target="_blank" rel="noreferrer">V2RayXS</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/OneXray/OneXray" target="_blank" rel="noreferrer">OneXray</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">macOS arm64 / x64</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/v2rayA/v2rayA" target="_blank" rel="noreferrer">v2rayA</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/2dust/v2rayN" target="_blank" rel="noreferrer">v2rayN</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/LorenEteval/Furious" target="_blank" rel="noreferrer">Furious</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/ketetefid/GorzRay" target="_blank" rel="noreferrer">GorzRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/goxray/desktop" target="_blank" rel="noreferrer">GoXRay</a></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><a href="https://github.com/AnyPortal/AnyPortal" target="_blank" rel="noreferrer">AnyPortal</a></td></tr></tbody></table><h2 id="uuid-生成器" tabindex="-1">UUID 生成器 <a class="header-anchor" href="#uuid-生成器" aria-label="Permalink to “UUID 生成器”">​</a></h2><p>第三方的 UUID 生成器 <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">uuidgenerator.net</a></p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};